draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'brown';
  ctx.fillRect(W/2-50, H/2-75, 100, 150);
  ctx.strokeRect(W/2-50, H/2-75, 100, 150);

  // pages
  ctx.fillStyle = 'white';
  ctx.fillRect(W/2-45, H/2-70, 90, 140);
  ctx.strokeRect(W/2-45, H/2-70, 90, 140);

  // stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2+100, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+80);
  ctx.lineTo(W/2, H/2+120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+100);
  ctx.lineTo(W/2-20, H/2+80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+100);
  ctx.lineTo(W/2+20, H/2+80);
  ctx.stroke();

  // wisdom
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Wisdom', W/2, H/2-150 + 50*Math.sin(t));

  // lesson
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Lesson', W/2, H/2-100 + 50*Math.cos(t));

  // life
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Life', W/2, H/2-50 + 50*Math.sin(t));

  // applying
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Applying', W/2, H/2 + 50*Math.cos(t));

  // 1692
  ctx.font = '48px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('1692', W/2, H/2+150 + 20*Math.sin(t));

  ctx.restore();
}
